"""Retain fifteen individual Greek/Roman/Byzantine house-figure proposals."""
from pathlib import Path
import json

ROOT = Path(__file__).resolve().parents[3]
REALM = ROOT / 'Vorschau/Leukonia'
PRESET = json.loads((ROOT/'AleriaAlmanach/docs/art/image-style-presets.json').read_text(encoding='utf-8'))['presets']['fantasy-rpg-character']['prompt']
HERALDRY = {job['id']:job for job in json.loads((REALM/'sources/heraldry-generation-jobs.json').read_text(encoding='utf-8'))['jobs']}
STYLE_REF = ROOT/'AleriaAlmanach/docs/art/character-style/2026-10-24-approved-house-knight.png'
HORSE_REF = ROOT/'Bestiarium/assets/horse-profiles/equo.webp'

DESIGNS = [
(18,4,'Eine junge erwachsene schlanke Fernkämpferin. Griechischer heller Linothorax über marineblauer Tunika, seitlich geschlitzter kurzer Rock mit silbernen Wellenborten, schlichte bronzeeiserne Beinschienen. Niedriger böotischer offener Helm mit breiter gewellter Krempe statt Helmkamm. Sie hält einen geraden Speer in der rechten Hand aufrecht; links ruht die Hand am Gürtel. Der Rückenköcher mit fünf klar erkennbaren Pfeilen sitzt hoch hinter der anderen Schulter. Silberner Fisch als kleine Stickerei auf dunkelblauem Schulterstoff, keine Fischrüstung.','Linothorax, Speer, Rückenköcher, böotischer Helm'),
(19,1,'Ein junger erwachsener schlanker schwerer Infanterist in byzantinischem silbernem Klivanion-Lamellenpanzer über schieferblauer Tunika. Geschlossener spätantiker Kammhelm mit einfacher vollständiger menschlicher Gesichtsmaske, schmalen Augenschlitzen und kurzem Kettennackenschutz, kein Eulengesicht. Breite klar gebaute Schulterlamellen. Er hält ein gerades Schwert locker mit der Spitze schräg nach unten und einen langen rechteckigen dunkelblauen Turmschild seitlich; darauf eine goldene Eule. Kleine Goldfedern als flache Gravur an den Armspangen.','Schwert, Turmschild, Klivanion, geschlossener Gesichtshelm'),
(20,7,'Ein junger erwachsener schlanker Kampfbarde mit leichter römischer Kettenweste, elfenbeinfarbener Tunika und schwarzem schmalem Schulterumhang. Niedriger offener attischer Helm ohne hohen Busch, kurze dunkle Locken an den Seiten. Ein schwarzer Rabe ist nur als feine Borte auf dem hellen Bruststoff zu sehen. In der rechten Hand hält er einen gebogenen Säbel mit der Spitze nach unten, im linken Arm stützt er eine kleine tragbare hölzerne Leier mit sichtbaren Saiten. Beide Hände, Griff und Leier sind plausibel getrennt. Ruhig, verschmitzter ernster Blick, nicht spielend während beide Hände Gegenstände halten.','Säbel, tragbare Leier, Kettenweste, attischer Helm'),
(21,1,'Eine junge erwachsene athletische schwere Infanteristin. Roter langer Waffenrock unter schwerer matter silberner Schuppenrüstung, kurze elfenbeinfarbene Fellkante nur am Kragen, keine Tierkopftrophäe. Geschlossener korinthischer Helm mit tiefem Nasal und langen eng anliegenden Wangenklappen, roter niedriger Längskamm. Sie hält eine einschneidige römisch-byzantinische Streitaxt aufrecht in der rechten Hand; die linke Hand ruht auf dem Gürtel. Ein kleines silbernes Bärenbild ist auf die rote Bauchschärpe gestickt. Kein weiterer Schild. Die Rüstung ist voll und funktional, nicht freizügig.','Streitaxt, schwerer Schuppenpanzer, geschlossener Korintherhelm'),
(22,3,'Ein junger erwachsener Kataphrakt auf einem Equo: dunkles fast schwarzes kräftiges Militärpferd mit schwarzer Mähne gemäß eigener Pferdereferenz. Reiter trägt bronzene kleine Schuppen über olivgrünem Gewand und geschlossenen spätrömischen Kammhelm mit menschlicher Vollmaske und niedrigem bronzenem Kamm. Sein gerades Reiterschwert hält er ruhig mit Spitze nach außen schräg abwärts. Das Pferd steht in anderer Dreiviertelansicht, Kopf nach rechts, alle vier Beine und Hufe getrennt sichtbar. Schlichte olivgrüne Satteldecke mit bronzenem Windhundmotiv, zurückhaltende bronzene Schuppen am Pferdehals. Zügel in der linken Hand, funktionierende Sattel-/Steigbügel, Schweif ausschließlich an der Hinterhand.','Reiterschwert, Schuppenpanzer, Vollmaskenhelm, Equo'),
(23,2,'Eine junge erwachsene hochgewachsene schwer gepanzerte Lanzenträgerin. Silberner byzantinischer Lamellenpanzer mit schwarzen Lederbindungen über weinrotem langem Untergewand, deutlich andere lange senkrechte Pteryges. Geschlossener konischer byzantinischer Helm mit angenieteter schlichter Gesichtsmaske, Kettenaventail und ohne Tierverzierungen. Der silberne Hirschkäfer ist als kleines Wappenschild auf dem Bruststoff und auf der Gürtelschließe dargestellt. Sie umfasst die lange gerade Lanze mit beiden Händen entspannt in Hüfthöhe; die ganze Spitze steht senkrecht sichtbar weit über dem Helm mit deutlichem freien Rand. Kein Schild.','Lange Lanze, Lamellenrüstung, geschlossener byzantinischer Maskenhelm'),
(24,6,'Ein junger erwachsener einfacher Legionär der Miliz. Schlichter matter Eisen-Montefortinohelm mit kleiner Spitze ohne hohen Federschmuck, einfache kurze Schuppenweste über petrolgrüner Tunika und naturfarbenen Beinwickeln. Einfache Ledersandalen und kleiner brauner Schulterumhang. Er hält einen einfachen kurzen geraden Gladius nach unten und einen mittelgroßen ovalen petrolfarbenen Holzschild mit kleiner mattgoldener Palme. Deutlich schlichter und leichter als die schweren Hauskrieger, nicht barfuß, kein prunkvoller Brustharnisch.','Gladius, ovaler Holzschild, schlichte Schuppenweste, Montefortinohelm'),
(25,4,'Ein junger erwachsener schlanker Fernkämpfer in griechischem bronzenem Brustpanzer mit hellem Leinenrock und kleinen roten Saumborten. Offener thrakischer Helm mit geschwungener nach vorn gebogener Kalotte und langen seitlichen Wangenklappen, kein Gesichtsschutz vor dem Mund. Ruhige offene Standhaltung. Er hält einen langen Speer in einer Hand; hinter der linken Schulter ist ein Rückenköcher mit deutlich sichtbaren Pfeilenden. Drei goldene Getreideähren mit roter Schleife als kleine Bemalung auf der cremefarbenen Brustschärpe. Keine weiteren Handgegenstände.','Speer, Rückenköcher, bronzener Brustpanzer, thrakischer Helm'),
(26,2,'Ein junger erwachsener stämmig-athletischer, aber nicht dicker Lanzenträger in spätrömischem silbernem Segmentpanzer mit breiter dunkelroter Leibschärpe und elfenbeinfarbenem Untergewand. Geschlossener römisch-griechischer Gesichtshelm mit tiefen verbundenen Wangenplatten, nur Augen- und kleine Atemschlitze offen, niedrigem schwarzem Kamm. Ein schlichtes Brückenmotiv ist als kleine silberne Stickerei am roten Tuch sichtbar. Lange schwere Hasta aufrecht in der rechten Hand, linke Hand auf einem kleinen seitlich stehenden dunkelroten Rundschild. Seine Silhouette ist kompakt mit breiten geschlossenen Schulterplatten.','Schwere Hasta, Rundschild, Segmentpanzer, geschlossener Gesichtshelm'),
(27,5,'Eine junge erwachsene edle Marinerin und Klerikerin des Zephyr. Pompöser byzantinischer Schuppenpanzer und marineblauer, heller und bronzefarbener Seidenstoff in großen lesbaren Bahnen; bronzene Wellenborten und ein kleiner silberner Leuchtturm als Brustbeschlag. Ein griechisch-byzantinischer Helm mit engen Wangenplatten, sichtbarem jugendlichem Gesicht und kurzem blauem Längsbusch. Sie hält einen gebogenen Paramerion-Säbel mit entspannter Klinge nach unten. Ein deutlich erkennbarer Rückenköcher mit Pfeilen ragt hinter ihrer Schulter hervor. Linke Hand locker am reich gearbeiteten Gürtel. Keine zusätzliche erdachte Götterstatue, kein Buch und kein weiteres Instrument. Ruhig, nobel und funktional gepanzert.','Säbel, Rückenköcher, edler Schuppenpanzer, byzantinischer Helm'),
(28,1,'Ein junger erwachsener schwerer Hoplit. Dunkelgrüne Tunika unter mattem goldenem griechischem Muskelpanzer, schwere Beinschienen, kurzer schwarzer Schulterumhang. Vollständig geschlossener korinthischer Helm mit schmalen Augenschlitzen, Nasenschutz und niedrigem dunkelgrünem Querbusch. Er hält ein gerades Schwert und einen großen runden dunkelgrünen Hoplon, auf den die achtstrahlige goldene Sonne gemalt ist. Das Sonnenmotiv erscheint zusätzlich als zurückhaltender Beschlag am Gürtel, keine strahlenden Energien oder magische Beleuchtung.','Schwert, großer Hoplon, Muskelpanzer, geschlossener Korintherhelm'),
(29,7,'Eine junge erwachsene schlanke Kampfbardin mit schlichter silberner römischer Schuppenweste, weichem purpurfarbenem kurzen Mantel und schwarzem Untergewand. Offener niedriger spätrömischer Kammhelm ohne hohen Federbusch, sichtbares freundliches junges Gesicht und ein kurzer dunkler Zopf. Eine silberne Mondsichel unter drei goldenen Sternen ist auf die Brust gestickt. Sie hält rechts einen Säbel ruhig mit Spitze nach unten und links eine kleine runde antike Rahmentrommel mit schlichten Bronzeschellen, nicht spielend. Die Trommel ist deutlich ein Instrument und kein Schild.','Säbel, Rahmentrommel, leichte Schuppenweste, spätrömischer Helm'),
(30,1,'Ein junger erwachsener athletischer schwerer Krieger mit schwerem silbernem byzantinischem Klivanion, rostrot bemaltem gepanzertem Lederschurz und schwarzem Mantel nur über einer Schulter. Geschlossener eiförmiger byzantinischer Vollvisierhelm mit deutlichem Nasenrücken und schmalen Augenöffnungen, ohne hohen Schmuck. Er hält eine lange schwere einschneidige Streitaxt in beiden Händen quer schräg vor dem Körper; zwei Hände umfassen einen einzigen geraden stabilen Holzschaft. Ein Paar gekreuzter kleiner silberner Äxte ist als Wappenmotiv auf die rostrote Bauchschärpe gestickt. Keine losen zweiten Waffen oder Schild.','Schwere Streitaxt, Klivanion, geschlossener byzantinischer Visierhelm'),
(31,3,'Eine junge erwachsene Kataphraktin auf einem dunklen Equo mit schwarzer Mähne gemäß Pferdereferenz. Edler matter goldener griechisch-byzantinischer Schuppenpanzer über dunkelrotem Untergewand, geschlossener phrygisch geformter Reiterhelm mit menschlicher Gesichtsmaske und kurzem tiefrotem Kamm. Kein Sphinxkopf- oder Tierkostüm. Das goldene Sphinxmotiv als kleine Stickerei auf roter Satteldecke und flacher Beschlag an der Brust. Reiterschwert in der rechten Hand ruhig mit Spitze nach unten, Zügel funktional links. Pferd in linker Dreiviertelansicht mit vier vollständigen Hufen, realistischer Sattel und Steigbügel; Schweif ausschließlich an der Hinterhand.','Reiterschwert, Schuppenpanzer, geschlossener Reiterhelm, Equo'),
(32,2,'Ein junger erwachsener hochgewachsener schwer gepanzerter Lanzenträger. Roter langer Waffenrock mit elfenbeinfarbenen Säumen unter dunklem eisernem Lamellenpanzer, auffällige aber funktionale senkrechte Metallleisten an der Brust greifen nur abstrakt das Leitermotiv auf. Geschlossener spätrömischer Kammhelm mit verbundenen Wangenplatten und schmalen Augenschlitzen, kurzer schwarzer Längskamm. Lange schwere Lanze rechts aufrecht; links ruht die Hand auf einem kleinen roten runden Schild mit silbernem Leitermotiv. Ganze Lanzenspitze und beide Füße frei im Bild.','Lange Lanze, Rundschild, dunkle Lamellenrüstung, geschlossener Kammhelm')
]

jobs=[]
for number, prototype, design, gear in DESIGNS:
    house_id=f'pool-{number:02}'
    emblem=HERALDRY[house_id]
    role={1:'Schwerer Infanterist',2:'Schwer gepanzerter Lanzenträger',3:'Berittener mit Schwert · Kataphrakt',4:'Fernkämpfer mit Speer und Rückenköcher',5:'Mariner und Kleriker des Zephyr',6:'Miliz · einfacher Legionär',7:'Römischer Kampfbarde'}[prototype]
    prompt='\n\n'.join([
        'Ein einzelner eigenständiger Hauskrieger für Leukonia im Fantasy-Kaiserreich Argentum. Bildentwurf einer Rolle, keine benannte Person und kein neuer Klassenname. Die erste Bildreferenz liefert ausschließlich den freigegebenen matten MALSTIL, niemals die westliche Plattenrüstung, deren Helm oder Farben. Die zweite Bildreferenz ist das konkrete Wappen und liefert nur dieses Hausmotiv und seine Farben.',
        PRESET,
        'NEUE AUSDRÜCKLICHE NUTZERVORGABE: Verschiedene griechische, römische und byzantinische Rüstungen und Helme. Bei schweren Truppengattungen häufig geschlossene Helme. Keine nordeuropäische Ritterrüstung als Standard. Keine bloße Umfärbung einer Standardfigur; individuelle Ausrüstung, Körperhaltung, Gesicht und Silhouette.',
        'Individuelles Motiv: '+design,
        'Hauspalette: '+', '.join(emblem['palette'])+'. Wappenmotiv: '+emblem['motif']+' Das Wappen bleibt nur sinnvoll getragene Bemalung, Stickerei oder Beschlag und wird nicht als separates schwebendes Wappen neben die Figur gezeichnet.',
        'Hochformat 2:3, PNG exakt1024x1536. Höchster Helmpunkt und ganze Waffenspitze bis beide vollständigen Füße beziehungsweise alle vier Pferdehufe sichtbar, mit bequemem freien Rand. Junge erwachsene menschliche Figur, normale menschliche Ohren, schlank bis athletisch. Keine alte oder dicke Person. Ruhige aufrechte Pose; echte transparente Außenfläche und offene Lücken. Kein Boden, Schatten, Farbdunst, Papierhintergrund, Text oder Rahmen. Alle Finger und Waffengriffe plausibel, keine verschmolzenen Waffenachsen. Metall matt und einfach gemalt, kein realistisches Portrait und keine glänzende 3D-Darstellung.'
    ])
    refs=[str(STYLE_REF),str(REALM/f'assets/emblems/production/{house_id}.png')]
    mount=None
    if prototype==3:
        refs.append(str(HORSE_REF))
        prompt+='\n\nDie dritte Referenz zeigt ausschließlich die echte Equo-Pferderasse, ein dunkles standardmäßiges Militärpferd Argentums. Keine Stallumgebung, weiteren Pferde oder Pferdepfleger kopieren. Genau ein Reiter auf genau einem Pferd, alle vier vollständigen Hufe und natürliche Hinterhand mit Schweif.'
        mount={'name':'Equo','href':'../../Bestiarium/tiere/pferde/equo/index.html'}
    jobs.append({'id':'warrior-'+house_id,'houseId':house_id,'assetStem':house_id,'category':'warriors','prototypeId':f'prototype-{prototype:02}','role':role,'description':design,'equipment':gear.split(', '),'palette':emblem['palette'],'mount':mount,'prompt':prompt,'transparent_background':True,'referenced_image_paths':refs})

manifest={'schemaVersion':1,'date':'2026-11-03','tool':'built-in image_gen.imagegen','status':'Individual noncanonical house figure proposals following the confirmed seven class roles.','jobs':jobs}
(REALM/'sources/house-warriors-pool-18-32-jobs.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2),encoding='utf-8')
print(json.dumps(jobs,ensure_ascii=False))
